class LengthReader:
    def __init__(self, unreader, length):
        self.unreader = unreader
        self.length = length

    def read(self, size):
        if not isinstance(size, int):
            raise TypeError("size must be an integral type")

        size = min(self.length, size)
        if size < 0:
            raise ValueError("Size must be positive.")
        if size == 0:
            return b""

        while self.length > 0:
            if self.length <= size:
                ret = self.unreader.read(self.length)
                self.length = 0
                return ret
            else:
                self.length -= size
                return self.unreader.read(size)

        return b""


class EOFReader:
    def __init__(self, unreader):
        self.unreader = unreader
        self.finished = False

    def read(self, size):
        if not isinstance(size, int):
            raise TypeError("size must be an integral type")

        size = min(8192, size)
        if size < 0:
            raise ValueError("Size must be positive.")
        if size == 0:
            return b""

        if self.finished:
            return b""

        return self.unreader.read(size)


